import rospy
from typing import Type, Callable, TYPE_CHECKING
from ..logger.logger import logger

if TYPE_CHECKING:
    from .node import ROS1Node


class ROS1Service:
    def __init__(
        self,
        node: "ROS1Node",
        srv_type: Type,
        service: str,
        callback: Callable,
        qos_profile: int = 10,
        **kwargs
    ):
        """
        创建ROS1服务服务器

        Args:
            node: ROS1Node实例
            srv_type: 服务类型
            service: 服务名称
            callback: 回调函数
            qos_profile: 队列大小（对应ROS2的qos_profile，ROS1中未使用）
            **kwargs: 其他参数传递给rospy.Service
        """
        self._node = node
        self._srv_type = srv_type
        self._service = service
        self._callback = callback
        self._server = rospy.Service(service, srv_type, callback, **kwargs)

    @property
    def service(self) -> str:
        """获取服务名称"""
        return self._service

    @property
    def srv_type(self) -> Type:
        """获取服务类型"""
        return self._srv_type

    def destroy(self):
        """销毁服务服务器"""
        self._server.shutdown()
